CREATE TABLE bulbs (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, name_normalized TEXT NOT NULL UNIQUE, ip_address TEXT NOT NULL UNIQUE, port INTEGER NOT NULL CHECK(port BETWEEN 1 AND 65535), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE profiles (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, name_normalized TEXT NOT NULL UNIQUE, dimmer INTEGER NOT NULL CHECK(dimmer BETWEEN 1 AND 100), mode TEXT NOT NULL CHECK(mode IN ('rgb','color_temperature')), rgb_color TEXT, color_temperature_kelvin INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK((mode='rgb' AND rgb_color GLOB '#[0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F]' AND color_temperature_kelvin IS NULL) OR (mode='color_temperature' AND rgb_color IS NULL AND color_temperature_kelvin BETWEEN 3000 AND 6000)));
CREATE TABLE reset_settings (singleton INTEGER PRIMARY KEY CHECK(singleton=1), dimmer INTEGER NOT NULL CHECK(dimmer BETWEEN 1 AND 100), mode TEXT NOT NULL CHECK(mode IN ('rgb','color_temperature')), rgb_color TEXT, color_temperature_kelvin INTEGER, CHECK((mode='rgb' AND rgb_color GLOB '#[0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F][0-9A-F]' AND color_temperature_kelvin IS NULL) OR (mode='color_temperature' AND rgb_color IS NULL AND color_temperature_kelvin BETWEEN 3000 AND 6000)));
INSERT INTO reset_settings(singleton,dimmer,mode,rgb_color,color_temperature_kelvin) VALUES(1,100,'color_temperature',NULL,3000);
